    // Risk Management - CHINESE
    positionSizingTitle: '仓位大小',
    positionSizingDesc: '根据您的风险承受能力和账户规模，确定在每笔交易中承担多少资本风险。',
    tradeInstrument: '品种',
    tradeInstrumentSpot: '现货 / 股票',
