    edu_comoLeerElDiagrama_0e91a1f2: '如何解读Payoff图',
    edu_elGraficoDePayoff_4228af6d: 'Payoff图显示PnL（Y轴）与到期时标的资产价格（X轴）的关系。两条关键线是T+0（今天）和At Expiry（到期时）。',
    edu_longCallBuyCall_b69bddbc: 'LONG CALL（BUY CALL）→ 支付Prima。当上涨 > Strike+Prima时盈利。最大损失 = 已付Prima。',
