    edu_shortPutSellPut_cc28336a: 'SHORT PUT（SELL PUT）→ 收取Prima。当下跌 < Strike−Prima时亏损。最大损失 = Strike−Prima（跌至0时）。',
    edu_regla802080_db62e282: '80/20法则 → 约80%的期权到期无价值 → 从统计上看Prima的卖方通常获胜；但其风险/收益比很差。',
    edu_deltaCambioEnPrima_0791393e: 'Delta Δ → 标的资产每变动$1时Prima的变化。CALL：0至+1。PUT：0至-1。',
